using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ShadowMasteryPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Moonie/ShadowMasteryPreviewDescription", order = 0)]
public class ShadowMasteryPreviewDescription : PreviewDescription
{
	public override string GetCustomPreviewDescription(string amountModified, BattleAction battleAction)
	{
		ShadowMasteryAction shadowMasteryAction = battleAction as ShadowMasteryAction;
		string text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("Purify_D"), shadowMasteryAction.GetPurifyAmount(0));
		return shadowMasteryAction.PlayerSelfDoomAction.GetActionDescription(shadowMasteryAction.GetDoomAmount(GetAmountWithoutEquation(amountModified)) + 1).RemoveLast() + "\n" + text;
	}
}
